8	/**
9	 * Create-time uniqueness guard for {@code POST /owners}. It rejects a request with a 409 via
10	 * {@link DuplicateIdentityException} for an <b>exact identity duplicate</b>: a request whose whole
11	 * {@link OwnerIdentity identityKey} (normalised telephone, email and the last name's Soundex
12	 * together) equals an existing owner's — a genuinely identical owner is always a duplicate.
13	 *
14	 * <p>Sharing a household is no longer a duplicate on its own: several members may belong to the
15	 * same household (same {@code lastName} and {@code postcode}, see {@link OwnerHousehold}) as long
16	 * as they differ in telephone or email, so their identity keys differ. A new member's standing is
17	 * instead bounded by the household level ceiling applied later in the pipeline (see
18	 * {@link CapMembershipLevel}), not by rejecting the create; a non-declared member is additionally
19	 * flagged as a <em>possible</em> duplicate (see {@link AssignPossibleDuplicate}).
20	 *
21	 * <p>The identity key folds the normalised telephone, email and the last name's Soundex together
22	 * (see {@link OwnerIdentity}); there is no longer any separate household-derived duplicate check.
23	 * Runs after {@link NormalizeOwnerTelephone} and {@link NormalizeOwnerEmail} (so the request's
24	 * telephone and email are in their stored, canonical forms) and before {@link BuildOwner}. The
25	 * disposable-email blocklist is applied earlier, in {@link NormalizeOwnerEmail}, so it is enforced
26	 * before this guard runs.
27	 */
28	public class CheckOwnerIdentityUnique {
29	
30	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
31	            throws DuplicateIdentityException {
32	        String identityKey = OwnerIdentity.key(request.getTelephone(), request.getEmail(),
33	                request.getLastName());
34	        for (Owner existing : ownerRepository.findAll()) {
35	            if (existing.isDeleted()) {
36	                continue; // a soft-deleted owner is not a duplicate
37	            }
38	            if (identityKey.equals(OwnerIdentity.of(existing))) {
39	                throw new DuplicateIdentityException(identityKey);
40	            }
41	        }
42	    }
43	}
